package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen0Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_Success() {
        // Arrange
        Comparable rowKey1 = (Comparable) "Row1";
        Comparable rowKey2 = (Comparable) "Row2";
        Comparable colKey1 = (Comparable) "Col1";
        Comparable colKey2 = (Comparable) "Col2";

        dataset.addObject("Value1_1", rowKey1, colKey1);
        dataset.addObject("Value1_2", rowKey1, colKey2);
        dataset.addObject("Value2_1", rowKey2, colKey1);
        dataset.addObject("Value2_2", rowKey2, colKey2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("Value1_1", dataset.getObject(rowKey1, colKey1));

        // Act
        dataset.removeColumn(colKey1);

        // Assert
        assertEquals(1, dataset.getColumnCount());
        assertEquals(colKey2, dataset.getColumnKey(0));

        // Check that data was removed from rows
        // Since colKey1 is gone, getObject for colKey1 should return null or behave as if removed
        // Based on the code, rowData.removeValue(columnKey) is called.
        assertEquals("Value1_2", dataset.getObject(rowKey1, colKey2));
        assertEquals("Value2_2", dataset.getObject(rowKey2, colKey2));

        List columnKeys = dataset.getColumnKeys();
        assertFalse(columnKeys.contains(colKey1));
        assertTrue(columnKeys.contains(colKey2));
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKey() {
        // Arrange
        Comparable colKey1 = (Comparable) "Col1";
        dataset.addObject("Value", (Comparable) "Row1", colKey1);

        // Act
        dataset.removeColumn((Comparable) "NonExistentKey");
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Arrange
        Comparable colKey = (Comparable) "Col1";

        // Act & Assert: Should throw exception because column doesn't exist
        try {
            dataset.removeColumn(colKey);
        } catch (UnknownKeyException e) {
            // Success: expected exception
        }
    }

    @Test
    public void testRemoveColumn_SingleColumn() {
        // Arrange
        Comparable rowKey = (Comparable) "Row1";
        Comparable colKey = (Comparable) "Col1";
        dataset.addObject("Data", rowKey, colKey);

        // Act
        dataset.removeColumn(colKey);

        // Assert
        assertEquals(0, dataset.getColumnCount());
        assertEquals(0, dataset.getRowCount()); // If rowData is empty after removeValue, check implementation
        // Note: The provided code doesn't remove the row itself, just the value from the row.
        // However, if the row's only value was removed, the row still exists in dataset.rows
        // but contains no values.
    }
}
